INSERT INTO `FlowDefinition` (`module`, `name`, `description`, `status`, `draft_graph`, `created_at`, `updated_at`)
SELECT 'SALES', 'Sales hand-offs (today’s rules)', 'Who holds an enquiry at each stage — the built-in rule, drawn: Internal Sales (the person set in Setup) prepares and negotiates; the field owner does the rest. Change a group or add stages to send them elsewhere.', 'DRAFT', '{"nodes":[{"id":"start","type":"trigger","data":{"event":"STAGE_ENTERED"},"position":{"x":300,"y":0}},{"id":"which","type":"stage_switch","data":{"cases":[{"id":"internal","label":"Internal Sales","stages":["REVIEW","CONCEPT","COSTING","COSTING_REVIEW","OFFER_RELEASED","NEGOTIATION"]},{"id":"field","label":"Field sales","stages":["NEW","CONTACTED","FOLLOW_UP","NEGOTIATION_FOLLOW_UP","WON","LOST"]}]},"position":{"x":300,"y":170}},{"id":"toInternal","type":"assign","data":{"to":"SETUP_HANDLER"},"position":{"x":60,"y":380}},{"id":"toOwner","type":"assign","data":{"to":"OWNER"},"position":{"x":380,"y":380}},{"id":"end","type":"end","data":{},"position":{"x":680,"y":380}}],"edges":[{"id":"e-start-next-which","source":"start","target":"which"},{"id":"e-which-internal-toInternal","source":"which","target":"toInternal","sourceHandle":"internal"},{"id":"e-which-field-toOwner","source":"which","target":"toOwner","sourceHandle":"field"},{"id":"e-which-other-end","source":"which","target":"end","sourceHandle":"other"}]}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)
WHERE NOT EXISTS (SELECT 1 FROM `FlowDefinition` WHERE `module` = 'SALES' AND `name` = 'Sales hand-offs (today’s rules)');

INSERT INTO `FlowDefinition` (`module`, `name`, `description`, `status`, `draft_graph`, `created_at`, `updated_at`)
SELECT 'SALES', 'Big offers need approval', 'An offer above ₹50 Lakh is held until approved; if rejected, whoever holds the enquiry is told why. Choose the approver, then publish.', 'DRAFT', '{"nodes":[{"id":"start","type":"trigger","data":{"event":"BEFORE_OFFER_SENT"},"position":{"x":300,"y":0}},{"id":"big","type":"if","data":{"match":"all","rules":[{"field":"event.offer_value_inr","op":"gt","value":5000000}]},"position":{"x":300,"y":160}},{"id":"approve","type":"approval","data":{"to":[{"who":"PERSON"}],"mode":"ANY","remind_hours":4,"escalate_hours":24},"position":{"x":120,"y":340}},{"id":"tell","type":"notify","data":{"to":[{"who":"HANDLER"}],"title":"Offer for {{ref_no}} not approved","message":"{{approval.decided_by}}: {{approval.comment}}"},"position":{"x":300,"y":540}},{"id":"end","type":"end","data":{},"position":{"x":560,"y":540}}],"edges":[{"id":"e-start-next-big","source":"start","target":"big"},{"id":"e-big-yes-approve","source":"big","target":"approve","sourceHandle":"yes"},{"id":"e-big-no-end","source":"big","target":"end","sourceHandle":"no"},{"id":"e-approve-approved-end","source":"approve","target":"end","sourceHandle":"approved"},{"id":"e-approve-rejected-tell","source":"approve","target":"tell","sourceHandle":"rejected"},{"id":"e-tell-next-end","source":"tell","target":"end"}]}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)
WHERE NOT EXISTS (SELECT 1 FROM `FlowDefinition` WHERE `module` = 'SALES' AND `name` = 'Big offers need approval');

INSERT INTO `FlowDefinition` (`module`, `name`, `description`, `status`, `draft_graph`, `created_at`, `updated_at`)
SELECT 'SALES', 'Late-stage loss alert', 'An enquiry lost at Costing Review or later tells the people you choose, with the reason and who it went to.', 'DRAFT', '{"nodes":[{"id":"start","type":"trigger","data":{"event":"ENQUIRY_LOST"},"position":{"x":300,"y":0}},{"id":"late","type":"if","data":{"match":"all","rules":[{"field":"event.from","op":"in","value":["COSTING_REVIEW","OFFER_RELEASED","FOLLOW_UP","NEGOTIATION","NEGOTIATION_FOLLOW_UP"]}]},"position":{"x":300,"y":160}},{"id":"tell","type":"notify","data":{"to":[{"who":"PERSON"}],"title":"{{ref_no}} lost at {{event.from}}","message":"{{customer}} — {{event.lost_reason}} (went to {{event.lost_to}}). Value {{value_inr}}."},"position":{"x":120,"y":340}},{"id":"end","type":"end","data":{},"position":{"x":420,"y":520}}],"edges":[{"id":"e-start-next-late","source":"start","target":"late"},{"id":"e-late-yes-tell","source":"late","target":"tell","sourceHandle":"yes"},{"id":"e-late-no-end","source":"late","target":"end","sourceHandle":"no"},{"id":"e-tell-next-end","source":"tell","target":"end"}]}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)
WHERE NOT EXISTS (SELECT 1 FROM `FlowDefinition` WHERE `module` = 'SALES' AND `name` = 'Late-stage loss alert');

